/** Billing cycles a plan can have. */
export const CYCLE = Object.freeze({ WEEK: 'weekly', MONTH: 'monthly', YEAR: 'yearly' });

/** Every supported cycle, as stored in the subscriptions file. */
export const CYCLES = Object.freeze(Object.values(CYCLE));

// a charge's worth of money in twelfths of a month: a week is 52/12 of a month, a year is 1/12 of one
const TWELFTHS_PER_CHARGE = { [CYCLE.WEEK]: 52, [CYCLE.MONTH]: 12, [CYCLE.YEAR]: 1 };

const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

/**
 * What a plan costs per month, in whole cents (rounded to the nearest cent).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyCents(sub) {
  return Math.round((sub.price * TWELFTHS_PER_CHARGE[sub.cycle]) / 12);
}

/**
 * What all the plans cost per month together, in whole cents. The exact amounts are added up and
 * rounded once, so rounding differences don't pile up across plans.
 * @param {Array<{ price: number, cycle: string }>} subs
 * @returns {number}
 */
export function monthlyTotalCents(subs) {
  return Math.round(subs.reduce((sum, s) => sum + s.price * (TWELFTHS_PER_CHARGE[s.cycle] ?? 0), 0) / 12);
}

/**
 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
 * Monthly and yearly charges fall on the day of the month of the first charge (`since`), or the last day of a
 * shorter month. Weekly charges fall every 7 days from `since`.
 * @param {{ cycle: string, since: string }} sub
 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  if (sub.since >= today) return sub.since;
  if (sub.cycle === CYCLE.WEEK) {
    return addDays(sub.since, Math.ceil(daysBetween(sub.since, today) / 7) * 7);
  }
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}
'''
